import{renderDiagram}from './visual.js?v=20261023-physicscomplete01';import{spaceFigure}from './spa1-figures.js?v=20261023-physicscomplete01';export function showSpa1(spec='system',w={}){let[kind,card]=spec.split(':');renderDiagram(w.title||'Explore space physics',w.label||'Original schematic · not to scale',spaceFigure({kind,state:card||'0',...w}).replaceAll('spa1-sun','spa1-view-sun'),'PHYSICS · SPACE');}
